using System.Buffers.Binary;
using System.Numerics;

namespace OBP.RAC1.Gameplay;

/// <summary>
/// Aridia's authored enemy identities and directly witnessed values, from the
/// original LEVEL2 overlay as regenerated by rac1-native-game's mkall:aridia.
/// Behaviour not supported by a source address is identified as a host policy.
/// </summary>
public static class Rac1AridiaEnemies
{
    public const int LevelId = 2;
    public const int Sandshark = 580;
    public const int Constructorbot = 612;
    public const int Nest = 668;

    // Nest update L2:0x2dcdf0 calls 0x2d6118 with native state 0x1b
    // and anim 11; the launch origin's vertical coordinate is nest Z+1.5.
    public const int NestReleasedSharkState = 27;
    public const int NestReleasedSharkSequence = 11;
    public const float NestReleaseHeight = 1.5f;
    // L2:0x2dcdc0 sends 2 * the game's 1/60-s frame scalar into vec2_set_length.
    public const float NestReleaseSpeedPerTick = 2f / 60f;
    public const int NestIntervalPvarOffset = 0xd4;

    public static bool IsEnemyClass(int nativeClass) =>
        nativeClass is Sandshark or Constructorbot or Nest;

    // L2:0x2d3fbc, 0x2d78d0, 0x2dcc0c set the respective PVar health floats.
    public static int InitialHealth(int nativeClass) => nativeClass switch
    {
        Sandshark => 1,
        Constructorbot => 3,
        Nest => 3,
        _ => throw new ArgumentOutOfRangeException(nameof(nativeClass)),
    };

    /// <summary>
    /// Nest L2:0x2dcc28 reads authored PVar+0xd4 as its initial timer (then
    /// passes it to frame_scale_i). This native NTSC-U host steps at 60 Hz.
    /// </summary>
    public static int ReadNestInitialWaitTicks(ReadOnlySpan<byte> pvar)
    {
        if (pvar.Length < NestIntervalPvarOffset + 4)
            throw new InvalidDataException("Aridia nest is missing its authored PVar timer.");
        int ticks = BinaryPrimitives.ReadInt32LittleEndian(pvar.Slice(NestIntervalPvarOffset, 4));
        if (ticks is < 0 or > 36000)
            throw new InvalidDataException("Aridia nest has an invalid authored initial wait.");
        return ticks;
    }
}

public enum Rac1AridiaEnemyPhase
{
    Buried,
    Emerging,
    Launched,
    Chasing,
    Biting,
    Guarding,
    WindingUp,
    Flaming,
    Recovering,
    Dead,
}

public readonly record struct Rac1AridiaEnemyFacts(
    Vector3 Position, Vector3 PlayerPosition, bool PlayerAlive, bool LineOfSight,
    int WaitingSharkCount = 0);

public readonly record struct Rac1AridiaEnemyFrame(
    Rac1AridiaEnemyPhase Phase, Vector3 Motion, float Yaw, int Sequence,
    bool DamagePlayer = false, bool SpawnSandshark = false, bool FlameActive = false)
{
    public bool Alive => Phase != Rac1AridiaEnemyPhase.Dead;
    public bool Buried => Phase == Rac1AridiaEnemyPhase.Buried;
}

/// <summary>
/// Deterministic 60-Hz Aridia controller. The nest/shark handoff and authored
/// initial timers are retail-witnessed. The remaining attack detection, action
/// durations, pathfinding, health damage and host contacts are provisional.
/// </summary>
public sealed class Rac1AridiaEnemySession
{
    private sealed class Entry(int nativeClass, float yaw, int nestInitialWaitTicks)
    {
        public int ClassId { get; } = nativeClass;
        public int Health { get; set; } = Rac1AridiaEnemies.InitialHealth(nativeClass);
        public Rac1AridiaEnemyPhase Phase { get; set; } =
            nativeClass == Rac1AridiaEnemies.Sandshark ? Rac1AridiaEnemyPhase.Buried : Rac1AridiaEnemyPhase.Guarding;
        public int Ticks { get; set; }
        public float Yaw { get; set; } = yaw;
        public int NestInitialWaitTicks { get; } = nestInitialWaitTicks;
        public int SpawnTimer { get; set; }
        public Vector3 LaunchMotion { get; set; }
        public float LaunchFallSpeed { get; set; }
        public bool WasReleasedFromNest { get; set; }
    }

    private readonly Dictionary<int, Entry> _entries = [];
    public int Count => _entries.Count;

    public void Register(int instanceIndex, int nativeClass, float yaw = 0, int nestInitialWaitTicks = 60)
    {
        if (!Rac1AridiaEnemies.IsEnemyClass(nativeClass) || nestInitialWaitTicks < 0)
            throw new ArgumentOutOfRangeException(nameof(nativeClass));
        if (!_entries.TryAdd(instanceIndex, new(nativeClass, yaw, nestInitialWaitTicks)))
            throw new InvalidOperationException($"Duplicate Aridia enemy instance {instanceIndex}.");
    }

    public int Health(int instanceIndex) => _entries[instanceIndex].Health;

    public bool CanReleaseFromNest(int instanceIndex)
    {
        var entry = _entries[instanceIndex];
        return entry.ClassId == Rac1AridiaEnemies.Sandshark && entry.Health > 0 &&
            entry.Phase == Rac1AridiaEnemyPhase.Buried;
    }

    /// <summary>
    /// L2:0x2d6118 transfers the pre-existing shark to the nest's launch
    /// position, faces it along the vector toward its authored home point,
    /// and enters state 27/sequence 11. No new entity identity is allocated.
    /// </summary>
    public bool ReleaseFromNest(int instanceIndex, Vector3 nestPosition, Vector3 sharkHome)
    {
        if (!CanReleaseFromNest(instanceIndex)) return false;
        var entry = _entries[instanceIndex];
        Vector2 heading = new(sharkHome.X - nestPosition.X, sharkHome.Y - nestPosition.Y);
        if (heading.LengthSquared() < 1e-8f)
            heading = new(MathF.Cos(entry.Yaw), MathF.Sin(entry.Yaw));
        else
            heading = Vector2.Normalize(heading);
        entry.Yaw = MathF.Atan2(heading.Y, heading.X);
        entry.LaunchMotion = new(heading.X * Rac1AridiaEnemies.NestReleaseSpeedPerTick,
            heading.Y * Rac1AridiaEnemies.NestReleaseSpeedPerTick, 0);
        entry.LaunchFallSpeed = 0;
        entry.WasReleasedFromNest = true;
        Enter(entry, Rac1AridiaEnemyPhase.Launched);
        return true;
    }

    public bool Damage(int instanceIndex, double nativeDamage)
    {
        var entry = _entries[instanceIndex];
        if (entry.Health <= 0 || !double.IsFinite(nativeDamage) || nativeDamage <= 0)
            return false;
        entry.Health = Math.Max(0, entry.Health - (int)Math.Ceiling(nativeDamage));
        if (entry.Health == 0) Enter(entry, Rac1AridiaEnemyPhase.Dead);
        return true;
    }

    public Rac1AridiaEnemyFrame Step(int instanceIndex, Rac1AridiaEnemyFacts facts)
    {
        var entry = _entries[instanceIndex];
        if (entry.Phase == Rac1AridiaEnemyPhase.Dead)
            return new(entry.Phase, Vector3.Zero, entry.Yaw, DeathSequence(entry.ClassId));

        entry.Ticks++;
        Vector3 delta = facts.PlayerPosition - facts.Position;
        float distance = MathF.Sqrt(delta.X * delta.X + delta.Y * delta.Y);
        bool seesPlayer = facts.PlayerAlive && facts.LineOfSight;
        if (entry.ClassId == Rac1AridiaEnemies.Sandshark)
            return StepSandshark(entry, delta, distance, seesPlayer);
        if (entry.ClassId == Rac1AridiaEnemies.Constructorbot)
            return StepConstructorbot(entry, delta, distance, seesPlayer);
        return StepNest(entry, facts.WaitingSharkCount);
    }

    private static Rac1AridiaEnemyFrame StepNest(Entry entry, int waitingSharks)
    {
        // L2:0x2dcc64 checks a countdown and looks for an eligible native
        // class-580 Moby. Unlike the earlier host approximation, it does not
        // depend on Ratchet being within an invented 12-unit trigger radius.
        if (entry.Phase == Rac1AridiaEnemyPhase.Guarding)
        {
            entry.SpawnTimer++;
            int wait = entry.NestInitialWaitTicks > 0 ? entry.NestInitialWaitTicks : 1;
            if (entry.SpawnTimer >= wait && waitingSharks > 0)
                Enter(entry, Rac1AridiaEnemyPhase.WindingUp);
        }
        if (entry.Phase == Rac1AridiaEnemyPhase.WindingUp)
        {
            // L2:0x2dcce0 checks whether native animation position == 10.
            // The host still uses a bounded tick approximation until native
            // per-clip backwards timing is supported by Rac1MobySequenceClock.
            if (entry.Ticks >= 10)
            {
                Enter(entry, Rac1AridiaEnemyPhase.Guarding);
                entry.SpawnTimer = 0;
                return new(entry.Phase, Vector3.Zero, entry.Yaw, 1, SpawnSandshark: waitingSharks > 0);
            }
            return new(entry.Phase, Vector3.Zero, entry.Yaw, 0);
        }
        return new(entry.Phase, Vector3.Zero, entry.Yaw, 1);
    }

    private static Rac1AridiaEnemyFrame StepSandshark(Entry entry, Vector3 delta, float distance, bool seesPlayer)
    {
        if (entry.Phase == Rac1AridiaEnemyPhase.Launched)
        {
            // Source state27/sequence11 is exact. Flight duration and gravity
            // still belong to the bounded host contact adapter.
            if (entry.Ticks < 30)
            {
                // Provisional host gravity so the +1.5-unit native spawn point
                // lands on Godot terrain instead of remaining suspended.
                entry.LaunchFallSpeed = MathF.Max(-.12f, entry.LaunchFallSpeed - .003f);
                return new(entry.Phase, entry.LaunchMotion + new Vector3(0, 0, entry.LaunchFallSpeed),
                    entry.Yaw, Rac1AridiaEnemies.NestReleasedSharkSequence);
            }
            Enter(entry, seesPlayer ? Rac1AridiaEnemyPhase.Chasing : Rac1AridiaEnemyPhase.Guarding);
        }
        // The host must not turn an already released native state-27 shark
        // back into a waiting state-26 candidate just because Ratchet moved
        // away. Native re-eligibility is controlled by the original class AI.
        if (entry.WasReleasedFromNest && entry.Phase == Rac1AridiaEnemyPhase.Guarding &&
            seesPlayer && distance < 8)
            Enter(entry, Rac1AridiaEnemyPhase.Chasing);
        if (entry.Phase == Rac1AridiaEnemyPhase.Buried && seesPlayer && distance < 8)
            Enter(entry, Rac1AridiaEnemyPhase.Emerging);
        if (entry.Phase == Rac1AridiaEnemyPhase.Emerging && entry.Ticks >= 18)
            Enter(entry, Rac1AridiaEnemyPhase.Chasing);
        if (entry.Phase == Rac1AridiaEnemyPhase.Chasing && (!seesPlayer || distance > 14))
            Enter(entry, entry.WasReleasedFromNest
                ? Rac1AridiaEnemyPhase.Guarding : Rac1AridiaEnemyPhase.Buried);
        if (entry.Phase == Rac1AridiaEnemyPhase.Chasing && seesPlayer && distance < 0.95f)
            Enter(entry, Rac1AridiaEnemyPhase.Biting);
        if (entry.Phase == Rac1AridiaEnemyPhase.Biting && entry.Ticks >= 36)
            Enter(entry, distance < 1.2f ? Rac1AridiaEnemyPhase.Biting : Rac1AridiaEnemyPhase.Chasing);

        if (entry.Phase is Rac1AridiaEnemyPhase.Chasing or Rac1AridiaEnemyPhase.Biting && distance > .001f)
            entry.Yaw = TurnTowards(entry.Yaw, MathF.Atan2(delta.Y, delta.X), .12f);
        Vector3 motion = entry.Phase == Rac1AridiaEnemyPhase.Chasing && distance > .6f
            ? new(MathF.Cos(entry.Yaw) * .065f, MathF.Sin(entry.Yaw) * .065f, 0)
            : Vector3.Zero;
        int sequence = entry.Phase switch
        {
            Rac1AridiaEnemyPhase.Emerging => 2,
            Rac1AridiaEnemyPhase.Chasing => 4,
            Rac1AridiaEnemyPhase.Biting => 5,
            _ => 1,
        };
        return new(entry.Phase, motion, entry.Yaw, sequence,
            DamagePlayer: entry.Phase == Rac1AridiaEnemyPhase.Biting && entry.Ticks == 12 && distance <= 1.05f);
    }

    private static Rac1AridiaEnemyFrame StepConstructorbot(Entry entry, Vector3 delta, float distance, bool seesPlayer)
    {
        bool inRange = seesPlayer && distance < 8.5f;
        if (entry.Phase == Rac1AridiaEnemyPhase.Guarding && inRange)
            Enter(entry, Rac1AridiaEnemyPhase.WindingUp);
        if (entry.Phase == Rac1AridiaEnemyPhase.WindingUp && entry.Ticks >= 18)
            Enter(entry, Rac1AridiaEnemyPhase.Flaming);
        if (entry.Phase == Rac1AridiaEnemyPhase.Flaming && entry.Ticks >= 65)
            Enter(entry, Rac1AridiaEnemyPhase.Recovering);
        if (entry.Phase == Rac1AridiaEnemyPhase.Recovering && entry.Ticks >= 42)
            Enter(entry, inRange ? Rac1AridiaEnemyPhase.WindingUp : Rac1AridiaEnemyPhase.Guarding);

        if (inRange && distance > .001f)
            entry.Yaw = TurnTowards(entry.Yaw, MathF.Atan2(delta.Y, delta.X), .055f);
        bool flaming = entry.Phase == Rac1AridiaEnemyPhase.Flaming;
        float sweep = flaming ? MathF.Sin((entry.Ticks / 65f - .5f) * MathF.PI) * .6f : 0;
        float targetAngle = distance > .001f ? MathF.Atan2(delta.Y, delta.X) : entry.Yaw;
        bool touches = flaming && inRange && distance < 4.8f &&
            MathF.Abs(ShortestAngle(entry.Yaw + sweep, targetAngle)) < .32f;
        return new(entry.Phase, Vector3.Zero, entry.Yaw + sweep,
            flaming ? 4 : entry.Phase == Rac1AridiaEnemyPhase.WindingUp ? 2 : 1,
            DamagePlayer: touches && entry.Ticks % 16 == 0, FlameActive: flaming);
    }

    private static int DeathSequence(int cls) => cls switch
    {
        Rac1AridiaEnemies.Sandshark => 6,
        Rac1AridiaEnemies.Constructorbot => 6,
        _ => 3,
    };

    private static void Enter(Entry entry, Rac1AridiaEnemyPhase phase)
    {
        entry.Phase = phase;
        entry.Ticks = 0;
    }

    private static float ShortestAngle(float from, float to) =>
        MathF.Atan2(MathF.Sin(to - from), MathF.Cos(to - from));

    private static float TurnTowards(float from, float to, float max) =>
        from + Math.Clamp(ShortestAngle(from, to), -max, max);
}
